package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.MergedIntoVO;

class MergedIntoValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of merged into of observed issue")
  void test_merged_into_value_holder_assign_plain_value() {
    Object holder = new Object();
    MergedIntoValueHolder<Object> value = new MergedIntoValueHolder<>(holder);
    Assertions.assertSame(holder, value.mergedInto("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getMergedIntoValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getMergedInto().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.mergedIntoNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getMergedIntoValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getMergedInto().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of merged into of observed issue")
  void test_merged_into_value_holder_assign_value_object() {
    Object holder = new Object();
    MergedIntoValueHolder<Object> value = new MergedIntoValueHolder<>(holder);
    MergedIntoVO vo = MergedIntoVO.from("one");
    Assertions.assertFalse(value.getMergedIntoValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.mergedInto(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMergedIntoValue().orElseThrow());
    Assertions.assertSame(holder, value.mergedInto(Optional.empty()));
    Assertions.assertFalse(value.getMergedIntoValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.mergedInto(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMergedIntoValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of merged into of observed issue against the original")
  void test_merged_into_value_holder_read() {
    Object holder = new Object();
    MergedIntoValueHolder<Object> value = new MergedIntoValueHolder<>(holder);
    MergedIntoVO vo = MergedIntoVO.from("one");
    MergedIntoVO other = MergedIntoVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getMergedIntoValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMergedInto(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readMergedInto(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.mergedInto(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMergedInto(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMergedInto(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of merged into of observed issue")
  void test_merged_into_value_holder_unset() {
    Object holder = new Object();
    MergedIntoValueHolder<Object> value = new MergedIntoValueHolder<>(holder);
    MergedIntoVO vo = MergedIntoVO.from("one");
    value.mergedInto(vo);
    Assertions.assertSame(holder, value.unsetMergedIntoIfMatches("mergedInto_other"));
    Assertions.assertTrue(value.getMergedIntoValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMergedIntoIfMatches("mergedInto"));
    Assertions.assertFalse(value.getMergedIntoValue().isPresent(),
        "The field name must clear the value");
    value.mergedInto(vo);
    Assertions.assertSame(holder, value.unsetMergedInto());
    Assertions.assertFalse(value.getMergedIntoValue().isPresent(), "Unset must clear the value");
  }
}
